const x=$json;
if(!['coupon_validate','coupon_preview','promotion_info'].includes(x.operation))
  throw new Error('promotion_invalid_operation');
if(typeof x.customer_id!=='string'||!x.customer_id.trim())
  throw new Error('promotion_missing_customer');
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel))
  throw new Error('promotion_invalid_channel');
if(['coupon_validate','coupon_preview'].includes(x.operation)){
  if(typeof x.coupon_code!=='string'||!x.coupon_code.trim()||x.coupon_code.length>100)
    throw new Error('promotion_invalid_coupon_code');
}
return [{json:{
  ...x,
  store_id:x.store_id||'default',
  coupon_code:x.coupon_code?.trim()||null,
  action_id:x.action_id||`${x.customer_id}:${x.operation}:${x.coupon_code||''}`
}}];

const req=$('Validate Promotion Request').first().json;
const c=$input.first()?.json||{};
return [{json:{
  operation:req.operation,
  customer_id:req.customer_id,
  channel:req.channel,
  store_id:req.store_id,
  coupon_code:req.coupon_code,
  action_id:req.action_id,
  customer_status:c.status||null,
  // WF-20 must evaluate the coupon against the current live cart where applicable.
  evaluation_mode:req.operation==='promotion_info'?'informational':'transactional_live_cart'
}}];

const req=$('Prepare WF-20 Promotion Request').first().json;
const r=$json;
if(r.commerce_status==='unavailable'){
  return [{json:{
    success:false,operation:req.operation,customer_id:req.customer_id,
    commerce_status:'unavailable',verified:false,
    promotion:null,
    error:{
      code:'COMMERCE_UNAVAILABLE',
      transactional_action_blocked:req.operation!=='promotion_info',
      fallback:req.operation==='promotion_info'
        ?'kb_informational_only'
        :'preserve_purchase_intent_and_retry_when_live'
    }
  }}];
}
return [{json:{
  success:Boolean(r.success),
  operation:req.operation,
  customer_id:req.customer_id,
  commerce_status:r.commerce_status||'available',
  verified:Boolean(r.verified && r.success),
  promotion:r.promotion||null,
  error:r.error||null
}}];

const x=$json;
if(x.success && !x.verified) throw new Error('promotion_success_without_verification');
if(x.success && x.commerce_status!=='available')
  throw new Error('promotion_success_without_live_commerce');
if(x.operation!=='promotion_info' && x.success && !x.promotion)
  throw new Error('promotion_missing_verified_result');
return [{json:x}];
